// ti.js – Teachers' Day card for Ms. Nguyễn Thị Mỹ Hạnh
// Music: "music.mp3" (Ruth B – Dandelions) must sit next to index.html.

const PH = { a: "data:image/jpeg;base64,", b: "data:image/jpeg;base64,", c: "data:image/jpeg;base64," }; // cropped photos, embedded as base64

const $ = s => document.querySelector(s);
const scenes = [...document.querySelectorAll(".scene")];
const LAST = scenes.length - 1;
const WAIT = [0, 11500, 11500, 11500, 11500, 11500, 11500, 11500, 0]; // ms per scene (0 = wait for the viewer)
const REDUCED = matchMedia("(prefers-reduced-motion: reduce)").matches;
const dots = $("#dots");
let cur = 0, busy = false, timer;

/* ---------- photos, words, dots, ambient dandelion seeds ---------- */
document.documentElement.style.setProperty("--photo", `url(${PH.a})`);
document.querySelectorAll("[data-ph]").forEach(i => (i.src = PH[i.dataset.ph]));
scenes.forEach(s => {
  let i = 0;
  s.querySelectorAll(".rv").forEach(el => {
    el.innerHTML = el.textContent.trim().split(/\s+/)
      .map(w => `<span class="w" style="--i:${i++}">${w}</span>`).join(" ");
  });
});
scenes.forEach(() => dots.append(document.createElement("i")));
const mark = () => [...dots.children].forEach((d, k) => d.classList.toggle("on", k === cur));
mark();
for (let n = 0; n < 22; n++) {
  const p = document.createElement("span");
  p.className = "seed";
  p.style.cssText = `left:${Math.random() * 100}%;--z:${10 + Math.random() * 16}px;--d:${12 + Math.random() * 12}s;` +
    `--l:${-Math.random() * 20}s;--x:${(Math.random() - 0.3) * 40}vw`;
  $("#petals").append(p);
}

/* ---------- 9 different transitions ---------- */
const GREEN = "#14381f", GOLD = "#f0b429", CREAM = "#f8f1df", EASE = "cubic-bezier(.7,0,.2,1)";
const fx = $("#fx");
const mk = (n, css) => {
  fx.innerHTML = "";
  return Array.from({ length: n }, (_, i) => {
    const d = document.createElement("div");
    d.style.cssText = "position:absolute;" + css(i);
    fx.append(d);
    return d;
  });
};
const run = (els, kf, delay) => Promise.all(els.map((e, i) =>
  e.animate(typeof kf === "function" ? kf(i) : kf, { duration: 800, delay: delay(i), easing: EASE, fill: "forwards" }).finished));
const rnd = () => Math.random() * 450;

// old scene plays "out", is swapped, new scene plays "in" (used by 3D flip and warp)
const two = (out, inn, oo = "50% 50%", io = "50% 50%") => async (o, n) => {
  const ev = { duration: 900, easing: EASE };
  o.style.transformOrigin = oo;
  await o.animate(out, { ...ev, fill: "forwards" }).finished;
  o.classList.remove("on"); o.getAnimations().forEach(a => a.cancel()); o.style.transformOrigin = "";
  n.style.transformOrigin = io; n.classList.add("on");
  await n.animate(inn, ev).finished;
  n.style.transformOrigin = "";
};

const EFFECTS = [
  // 0 – dandelion wind: a golden haze rolls in while seeds are blown across the screen
  () => {
    const els = mk(1, () => `inset:0;background:radial-gradient(circle at 25% 65%,#fffdf2,#f3e3a8 75%)`);
    for (let i = 0; i < 45; i++) {
      const s = document.createElement("div");
      s.className = "seed";
      s.style.cssText = `left:-6%;top:${Math.random() * 100}%;--z:${12 + Math.random() * 28}px`;
      fx.append(s);
      s.animate([{ transform: "translate(0,0) rotate(0)" },
        { transform: `translate(115vw,${-35 + Math.random() * 25}vh) rotate(720deg)` }],
        { duration: 1500, delay: Math.random() * 250, easing: "ease-in", fill: "forwards" });
    }
    return { els, a: [{ opacity: 0 }, { opacity: 1 }], b: [{ opacity: 1 }, { opacity: 0 }], d: () => 0 };
  },
  // 1 – 3D door flip: the scene swings away on its left edge, the next swings in from the right
  () => ({ fn: two([{ transform: "rotateY(0)", opacity: 1 }, { transform: "rotateY(-85deg)", opacity: 0 }],
                   [{ transform: "rotateY(85deg)", opacity: 0 }, { transform: "rotateY(0)", opacity: 1 }], "0 50%", "100% 50%") }),
  // 2 – iris: the new scene opens like a circle from the centre
  () => ({ fn: async (o, n) => {
    n.classList.add("on", "top");
    await n.animate([{ clipPath: "circle(0% at 50% 50%)" }, { clipPath: "circle(75% at 50% 50%)" }], { duration: 1500, easing: EASE }).finished;
    o.classList.remove("on"); n.classList.remove("top");
  } }),
  // 3 – warp: the scene rushes toward you and blurs away; the next one arrives from far away
  () => ({ fn: two([{ transform: "scale(1)", filter: "blur(0)", opacity: 1 }, { transform: "scale(2.6)", filter: "blur(18px)", opacity: 0 }],
                   [{ transform: "scale(.4)", filter: "blur(18px)", opacity: 0 }, { transform: "scale(1)", filter: "blur(0)", opacity: 1 }]) }),
  // 4 – blinds: golden and green strips drop like a garden trellis
  () => ({
    els: mk(8, i => `top:0;bottom:0;left:${i * 12.5}%;width:12.6%;transform-origin:top;background:${i % 2 ? GOLD : GREEN}`),
    a: [{ transform: "scaleY(0)" }, { transform: "scaleY(1)" }],
    b: [{ transform: "scaleY(1) translateY(0)" }, { transform: "scaleY(1) translateY(101%)" }],
    d: i => i * 70
  }),
  // 5 – garden gates: two doors close, then swing open
  () => ({
    els: mk(2, i => `top:0;bottom:0;${i ? "right" : "left"}:0;width:50.5%;background:${GREEN};border-${i ? "left" : "right"}:4px solid ${GOLD}`),
    a: i => [{ transform: `translateX(${i ? 101 : -101}%)` }, { transform: "translateX(0)" }],
    b: i => [{ transform: "translateX(0)" }, { transform: `translateX(${i ? 101 : -101}%)` }],
    d: () => 0
  }),
  // 6 – mosaic: tiles pop in at random, then vanish at random
  () => ({
    els: mk(48, i => `left:${(i % 8) * 12.5}%;top:${(i / 8 | 0) * 16.67}%;width:12.6%;height:16.7%;background:${(i + (i / 8 | 0)) % 2 ? GREEN : "#1f5a37"}`),
    a: [{ transform: "scale(0)" }, { transform: "scale(1.02)" }],
    b: [{ opacity: 1 }, { opacity: 0 }],
    d: rnd
  }),
  // 7 – bloom: a golden flower of light grows, then fades
  () => ({
    els: mk(1, () => `inset:0;border-radius:50%;background:radial-gradient(circle,#fffbe8 0,${GOLD} 45%,#c98a0f 100%)`),
    a: [{ transform: "scale(0)" }, { transform: "scale(2)" }],
    b: [{ opacity: 1 }, { opacity: 0 }],
    d: () => 0
  }),
  // 8 – light sweep (used when watching again)
  () => ({
    els: mk(1, () => `top:-10%;bottom:-10%;left:-15%;width:130%;background:linear-gradient(100deg,${GREEN} 40%,${GOLD} 40% 46%,${CREAM} 46%)`),
    a: [{ transform: "skewX(-14deg) translateX(-125%)" }, { transform: "skewX(-14deg) translateX(0)" }],
    b: [{ transform: "skewX(-14deg) translateX(0)" }, { transform: "skewX(-14deg) translateX(125%)" }],
    d: () => 0
  })
];

async function go(n) {
  if (busy) return;
  busy = true;
  clearTimeout(timer);
  const old = scenes[cur], next = scenes[n];
  if (REDUCED) { old.classList.remove("on"); next.classList.add("on"); }
  else {
    const e = EFFECTS[n ? (n - 1) % 8 : 8]();
    if (e.fn) await e.fn(old, next);
    else {
      await run(e.els, e.a, e.d);
      old.classList.remove("on"); next.classList.add("on");
      await run(e.els, e.b, e.d);
    }
    fx.innerHTML = "";
  }
  cur = n; mark();
  busy = false;
  if (WAIT[cur]) timer = setTimeout(() => go(cur + 1), WAIT[cur]);
}

/* ---------- music ---------- */
let audio, muted = false;
function startMusic() {
  audio = new Audio("music.mp3");
  audio.loop = true;
  audio.volume = 0.8;
  audio.play().catch(() => {});
}
$("#mute").addEventListener("click", () => {
  muted = !muted;
  if (audio) audio.muted = muted;
  $("#mute").textContent = muted ? "✕" : "♪";
});
$("#open").addEventListener("click", () => { if (!audio) startMusic(); go(1); });
$("#replay").addEventListener("click", () => go(0));
